-- 251: menu-level alias and ratings category on the item glossary (Pranjay's go, 6 Nov 2026)
-- The production alias merges flavours (every cheesecake slice = Eggless Cheesecake Slice),
-- which the sales dashboard wants and a ratings read cannot afford. menu_alias merges only
-- spellings, sizes, sets, combos and occasion versions of one product. menu_category is the
-- twelve-value FORMAT vocabulary of cc-ratings/categories.json. Also adds the Zomato export
-- names the glossary had never seen (keyed on Petpooja names until now). Audit trigger fires.
begin;
alter table public.item_glossary add column if not exists menu_alias text;
alter table public.item_glossary add column if not exists menu_category text;
alter table public.item_glossary drop constraint if exists item_glossary_menu_category_chk;
alter table public.item_glossary add constraint item_glossary_menu_category_chk check (menu_category is null or menu_category in ('Cakes', 'Bento Cakes', 'Cheesecakes', 'Pastries & Slices', 'Tubs & Jars', 'Desserts', 'Croissants & Breads', 'Cookies & Brownies', 'Sweet Snacks', 'Savoury Snacks', 'Hampers', 'Add-ons'));
comment on column public.item_glossary.menu_alias is 'Menu-level alias for ratings: merges spellings, sizes, sets, combos and occasion versions of one product, never flavours (6 Nov 2026)';
comment on column public.item_glossary.menu_category is 'Format category for ratings, from cc-ratings/categories.json (6 Nov 2026)';
update public.item_glossary set menu_alias='Ted Lasso''s Boss Biscuit', menu_category='Cookies & Brownies', updated_at=now(), updated_by='pranjay@cremecastle.in (via Claude)' where item_name='Ted Lasso?s Boss Biscuit';
